// Builds the instructor walkthrough deck for the property-transfer case page:
//   site/probate-help/walkthrough/index.html   (the deck; same engine as /probate-help/)
//   docs/walkthrough-narration.txt             (the narration, one paragraph per slide, for recording)
// The family in the examples is FICTIONAL. Run: node tools/build-walkthrough.mjs
// Keep the spoken text (`say`) free of digits and abbreviations a voice would misread: it is also the caption text.
import fs from "fs";
const root = new URL("../", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// ---- page replica pieces -------------------------------------------------------------------------------------------
const B = (n) => (n ? `<i class="bd">${n}</i>` : "");
const F = (n, label, value = "", o = {}) =>
  `<label class="fl${o.hl === false ? "" : " hl"}">${B(n)}<span class="lb">${esc(label)}</span><span class="in${o.area ? " ar" : ""}${value ? "" : " empty"}">${esc(value || o.ph || "")}</span></label>`;
const SEL = (n, label, value) => `<label class="fl hl">${B(n)}<span class="lb">${esc(label)}</span><span class="in sl">${esc(value)}<b>▾</b></span></label>`;
const CHK = (n, label, on = true) => `<label class="fl hl ck">${B(n)}<span class="cbx${on ? " on" : ""}">${on ? "✓" : ""}</span><span class="lb">${esc(label)}</span></label>`;
const BTN = (n, label, kind = "") => `<span class="bt hl ${kind}">${B(n)}${esc(label)}</span>`;
const G2 = (a, b) => `<div class="g2">${a}${b}</div>`;
const CARD = (title, inner, meta = "") => `<div class="pc"><h4>${esc(title)}</h4>${meta ? `<p class="mt">${esc(meta)}</p>` : ""}${inner}</div>`;
const FRAME = (inner) => `<div class="fr"><div class="bar2"><span></span><span></span><span></span><em>2ndchinc.org/staff/deeds/transfer/</em></div><div class="pg">${inner}</div></div>`;
const ROOM = (items, head = "In the room") => `<div class="room"><h4>${head}</h4><ol>${items.map((t) => `<li>${t}</li>`).join("")}</ol></div>`;
const STEP = (title, text, o = {}) => `<div class="pc st"><h4><span class="sn">${o.n || ""}</span>${esc(title)}</h4><p class="mt">${esc(text)}</p>`
  + (o.dec ? `<div class="dec">${B(o.decN)}<b>${esc(o.dec.q)}</b>${o.dec.c.map((c, i) => `<span class="ch${i === (o.dec.pick ?? -1) ? " on" : ""}">${esc(c)}</span>`).join("")}</div>` : "")
  + (o.links ? `<div class="lk">${o.links.map((l) => `<span>${esc(l)}</span>`).join("")}</div>` : "")
  + `<div class="ctl2"><span class="in sl hl">${B(o.sN)}${esc(o.status || "To do")}<b>▾</b></span><span class="in hl">${B(o.dN)}target ${esc(o.due || "mm/dd/yyyy")}</span></div>`
  + `<span class="in hl wide${o.note ? "" : " empty"}">${B(o.nN)}${esc(o.note || "Note (case number, document number, date, who was told)")}</span></div>`;

const slides = [];
const add = (s) => slides.push(s);
const FIC = "Practice example: a fictional family. No real person is shown.";

// ---- PART 1: orientation -------------------------------------------------------------------------------------------
add({ part: "Welcome", kind: "cover", h: `Fill in your case page <span class="lead">together.</span>`, sub: "An instructor-led walkthrough of the property transfer page, field by field, using a practice family.",
  say: `Welcome. This is the walkthrough for your case page. I am your instructor, and over the next while we will go through the page together, one card and one field at a time, the way you will use it when you are gathering information for your own case. We use a practice family so no real person is shown. Press play, or use the arrows, and follow along.` });

add({ part: "Welcome", h: `How this <span class="gold">walkthrough</span> works.`, body: `<div class="grid3">
  <div class="box top"><h3>Numbered circles</h3><p class="small">Each slide shows the page the way you will see it. A gold number marks a field, and the same number on the right tells you what to ask and what to type.</p></div>
  <div class="box top"><h3>A practice family</h3><p class="small">Delia Marsh, who owned two parcels in Chicago, has died. Her four children are gathering the facts. Every name, address and number here is made up.</p></div>
  <div class="box top"><h3>Nothing is filed here</h3><p class="small">This page is for gathering and preparing. A lawyer reviews and files. We are not a law firm and nothing here is legal advice.</p></div></div>
  <div class="note"><b>Rule for every slide:</b> if you do not know a fact, leave the field blank. Do not guess. A blank is honest, and the page keeps track of what is still missing.</div>`,
  say: `Here is how this walkthrough works. Each slide shows the page the way you will see it. A gold number marks a field. The same number on the right tells you what to ask and what to type. Our practice family is made up. Delia Marsh owned two parcels in Chicago and has died, and her four children are gathering the facts. Nothing is filed from this page. A lawyer reviews and files. And one rule for every slide: if you do not know a fact, leave the field blank. Do not guess.` });

add({ part: "Welcome", h: `Before we start, <span class="lead">gather these.</span>`, body: `<ol class="asks">
  <li>A certified copy of the death certificate, or the details from it.</li><li>The recorded deed that shows who owns the property, and each parcel number, called a P I N.</li>
  <li>Names, addresses and phone numbers for every child, and for a surviving spouse if there is one.</li><li>The will, if there is one, and who holds the original.</li>
  <li>Her mail, bills and statements, so we can list what she owed and owned.</li><li>Tax bills, mortgage statements, and a note of who lives in the property and pays what.</li></ol>`,
  say: `Before we start, gather a few things. A certified copy of the death certificate, or at least the details from it. The recorded deed that shows who owns the property, and each parcel number, which is called a P I N. Names, addresses and phone numbers for every child, and for a surviving spouse if there is one. The will, if there is one, and who holds the original. Her mail, bills and statements. And the tax bills, any mortgage statements, and a note of who lives in the property. You do not need all of it today. The page tells you what is still missing.` });

add({ part: "Getting in", h: `Open the page and <span class="gold">sign in.</span>`, left: FRAME(CARD("Sign in", `<div class="fl hl">${B(1)}<span class="lb">Your staff email</span><span class="in">name@example.org</span></div><div class="fl hl">${B(2)}<span class="lb">Code from your email</span><span class="in">••••••</span></div><div class="fl hl">${B(3)}<span class="lb">Code from your authenticator app</span><span class="in">••••••</span></div>`, FIC)),
  right: ROOM([`The address is <b>2ndchinc.org/staff/deeds/transfer</b>. Bookmark it.`, `You are sent a six digit code by email. Type it in.`, `Then the six digit code from your authenticator app. Both are required.`, `Staff only. A case opens only for the people listed on it.`]),
  say: `First, open the page at two N D C H I N C dot org, slash staff, slash deeds, slash transfer. Bookmark it. Number one, type your staff email. Number two, we send a six digit code to that email, and you type it in. Number three, you type the six digit code from your authenticator app. Both are required, every time. This page is for staff, and each case opens only for the people listed on it, so a stranger who finds the address sees nothing.` });

add({ part: "Getting in", h: `Pick a case, or <span class="lead">start a new one.</span>`, left: FRAME(`<div class="pc"><div class="fl hl">${B(1)}<span class="lb">Case</span><span class="in sl">Marsh – 4410 S Example Ave<b>▾</b></span></div><div style="margin-top:8px">${BTN(2, "New case", "pri")}</div></div>` + CARD("New case", `${SEL(3, "What kind of case", "The owner died: the heir needs to become the deed owner")}<div style="margin-top:8px">${BTN(4, "Create case", "pri")}</div>`)),
  right: ROOM([`The <b>Case</b> list holds every case you may open. Pick one to work on it.`, `<b>New case</b> starts a fresh one.`, `Choose the kind. For a family after a death, it is the first choice.`, `Create it. Then the property card opens, and we fill it in.`]),
  say: `After you sign in you see your cases. Number one, the case list. Pick a case to work on it. Number two, new case starts a fresh one. Number three, choose the kind of case. For a family after a death, it is the first choice: the owner died, and the heir needs to become the deed owner. Number four, create it. Now the case opens and we fill it in from the top.` });

add({ part: "Getting in", h: `The page <span class="gold">at a glance.</span>`, left: FRAME(`<div class="pc">${B(1)}<h4>What's next</h4><p class="mt">Open items, with the nearest date first.</p></div><div class="pc">${B(2)}<div class="bar3"><i style="width:18%"></i></div><p class="mt">3 of 17 steps done (more steps appear as you answer the questions)</p></div><div class="pc">${B(3)}<h4>The property · Heirs · Death certificate · Court costs · Timeline · more cards</h4></div><div class="pc">${B(4)}<h4>The steps, in order, at the bottom</h4></div><div class="sync hl">${B(5)}Saved</div>`),
  right: ROOM([`<b>What's next</b> lists what to do now and what is overdue.`, `The <b>progress bar</b> counts steps done. More steps appear as you answer the questions.`, `The <b>cards</b> hold the facts you enter, from the top down.`, `The <b>steps</b> are the guided path. They fill in as the facts and choices come in.`, `A bar shows <b>Saving, Saved, Unsaved</b> or a conflict if two people edit at once.`]),
  say: `Here is the whole page at a glance. Number one, the card called what's next, which lists what to do now and anything overdue. Number two, the progress bar, which counts steps done. More steps appear as you answer the questions. Number three, the cards. These hold the facts you enter, from the top down. Number four, the steps, down at the bottom, which are the guided path. And number five, a small bar that tells you whether your work is saving, saved, or unsaved. If two people edit at once, it warns you, so nothing is silently overwritten.` });

// ---- PART 2: the property ------------------------------------------------------------------------------------------
add({ part: "The property", h: `The property card: <span class="lead">where and what.</span>`, left: FRAME(CARD("The property", `${G2(F(1, "Title (staff label)", "Marsh – 4410 S Example Ave"), F(2, "Property address", "4410 S Example Ave, Chicago, IL 60609"))}${G2(F(3, "Parcel numbers (PINs)", "20-00-000-001-0000; 20-00-000-002-0000"), F(4, "County", "Cook"))}`, FIC)),
  right: ROOM([`A short label so staff can find the case. Last name and street works well.`, `The street address of the property, with city, state and ZIP.`, `<b>Every</b> parcel number, separated by semicolons. One search does not cover the others.`, `The county where the property sits.`]),
  say: `Now we fill in the property card. Number one, the title. This is only a label so staff can find the case. Last name and street works well. Number two, the street address of the property, with city, state and zip. Number three, the parcel numbers, called P I Ns. List every one, separated by semicolons. Our practice family has two. This matters, because a search or a tax bill for one parcel says nothing about another. Number four, the county where the property sits.` });

add({ part: "The property", h: `The legal description, <span class="gold">copied exactly.</span>`, left: FRAME(CARD("The property", F(1, "Legal description", "LOTS 1 AND 2 IN BLOCK 3 IN SAMPLE SUBDIVISION OF PART OF THE SOUTHEAST QUARTER OF SECTION 00, TOWNSHIP 00 NORTH, RANGE 00 EAST OF THE THIRD PRINCIPAL MERIDIAN, IN COOK COUNTY, ILLINOIS. (Example text only.)", { area: true }), FIC)),
  right: ROOM([`Copy it from the <b>recorded deed</b> word for word. Do not retype from memory and do not shorten it.`, `If there are two parcels, include the description for each.`, `If you cannot find it yet, leave it blank. The deed paperwork will not print without it, and the page will say so.`]),
  say: `Next, the legal description. Number one. Copy it from the recorded deed, word for word. Do not retype it from memory and do not shorten it, because a deed is only as good as its legal description. If the property has two parcels, include the description for each. If you cannot find it yet, leave it blank. The deed paperwork will not be allowed to print without it, and the page will tell you that it is missing.` });

add({ part: "The property", h: `Who died, and <span class="lead">when.</span>`, left: FRAME(CARD("The property", `${G2(F(1, "Owner of record who died", "Delia Ann Marsh"), F(2, "Date of death", "03/14/2026"))}<p class="mt hl2">${B(3)}Other names on record: Delia A. Marsh; Delia Marsh-Hill.</p><div style="margin-top:8px">${BTN(4, "Save property details", "pri")}</div>`, FIC)),
  right: ROOM([`The owner <b>as the recorded deed names her</b>, not as the family calls her.`, `The date of death. The death certificate step will confirm it later.`, `The page lists other names it finds in the records. Keep that in mind for the name check later.`, `<b>Save</b> after you finish the card.`]),
  say: `Now, who died and when. Number one, the owner of record who died. Type her name exactly as the recorded deed names her, not as the family calls her. Number two, the date of death. The death certificate will confirm it in a moment. Number three is not a field. The page shows other names it finds in the records, and we will use those in the name check later. Number four, press save property details. The page saves as you go, but this button confirms the card is complete.` });

// ---- PART 3: death certificate -------------------------------------------------------------------------------------
add({ part: "Death certificate", h: `Upload the certificate, <span class="gold">let the page read it.</span>`, left: FRAME(CARD("Death certificate", `<div class="rw">${B(1)}<span class="in">Choose file</span>${BTN(2, "Upload", "")}<span class="bt">View</span></div><p class="mt">Uploaded: certificate-scan.pdf. The details below were filled in from it. Check every one against the paper.</p>`, FIC)),
  right: ROOM([`Choose the scan or photo of the certified certificate. A clear PDF is best.`, `Press upload. The page reads the document and fills the boxes on the next slides.`, `<b>Always check</b> what it filled in against the paper. A reading can be wrong.`]),
  say: `The death certificate card. Number one, choose the file, a scan or clear photo of the certificate. A P D F works best. Number two, press upload. The page reads the document and fills in the boxes you will see next. Here is the important habit: always check what it filled in against the paper itself. A machine reading can be wrong, and you are the one who confirms it. The original stays in your safe folder. It is never sent anywhere you did not choose.` });

add({ part: "Death certificate", h: `Name, birth date and <span class="lead">where she died.</span>`, left: FRAME(CARD("Death certificate", `${G2(F(1, "Full name as on the certificate", "Delia Ann Marsh"), F(2, "Date of birth", "06/02/1941"))}${G2(F(3, "Place of death (city, county, state)", "Chicago, Cook, Illinois"), F(4, "County of residence at death", "Cook"))}`, FIC)),
  right: ROOM([`Her full legal name, spelled exactly as the certificate shows it.`, `Her date of birth.`, `Where she died.`, `The county where she <b>lived</b>. This often decides which court hears the case, so read it carefully.`]),
  say: `Back on the death certificate card. Number one, her full name exactly as the certificate shows it. Number two, her date of birth. Number three, where she died: city, county and state. Number four, the county where she lived at the time of death. Read this one carefully. It often decides which court hears the case, and if she lived outside Cook County, the page will warn you that counsel must confirm where to file.` });

add({ part: "Death certificate", h: `Home address, <span class="gold">marital status, spouse.</span>`, left: FRAME(CARD("Death certificate", `${F(1, "Address of residence at death (street, city, state, ZIP)", "4410 S Example Ave, Chicago, IL 60609")}${G2(F(2, "Marital status", "Widowed"), F(3, "Surviving spouse", "None"))}${G2(F(4, "Certificate number", "EXAMPLE-0001"), F(5, "Date issued", "03/30/2026"))}`, FIC)),
  right: ROOM([`Her home address at death, as the certificate shows it.`, `Marital status.`, `A surviving spouse changes who inherits and who may serve. Write <b>None</b> only if the certificate says so.`, `The certificate number.`, `The date the certificate was issued.`]),
  say: `More of the same card. Number one, her address at death. Number two, her marital status. Number three, the surviving spouse. This one matters. A living spouse changes who inherits and who has the first right to serve, so write none only if the certificate says so. Number four, the certificate number. Number five, the date it was issued. These details go straight into the counsel packet, so accuracy matters more than speed.` });

add({ part: "Death certificate", h: `Informant, copies, and <span class="lead">only four digits.</span>`, left: FRAME(CARD("Death certificate", `${G2(F(1, "Informant", "Marcus Marsh (son)"), F(2, "Certified copies obtained and who holds them", "3 certified copies; Marcus holds them"))}${G2(F(3, "Social Security number, last four digits only", "1234"), F(4, "Date of death (also in the property card)", "03/14/2026"))}<div class="rw">${BTN(5, "Save certificate details", "pri")}${BTN(6, "Use this name as the owner who died", "")}</div>`, FIC)),
  right: ROOM([`The informant is the person who gave the information to the registrar.`, `How many certified copies exist and who holds them. You will need several.`, `<b>Last four digits only.</b> Never type the full number anywhere on this page.`, `This should match the property card. If it does not, find out why.`, `Save the certificate details.`, `If the certificate name differs from the deed, this button copies it to the property card. Use it only after you understand the difference.`]),
  say: `The last part of the death certificate card. Number one, the informant, who is the person who gave the information to the registrar. Number two, how many certified copies you have and who holds them. You will need several. Number three, the last four digits of her Social Security number, and only the last four. Never type the full number anywhere on this page. Number four, the date of death, which should match the property card. If it does not, find out why. Number five, save. Number six, use this name as the owner who died. Press it only after you understand why the certificate name differs from the deed.` });

// ---- PART 4: heirs -------------------------------------------------------------------------------------------------
add({ part: "Heirs", h: `The heirs card: <span class="gold">everyone who may have a share.</span>`, left: FRAME(CARD("Heirs and others who may have a share", `<div class="rw">${BTN(1, "+ Add a person", "pri")}</div><div class="rw">${BTN(2, "Print the affidavit of heirship")}${BTN(3, "Print all envelopes")}</div><div class="hr hl">${B(4)}<b>Marcus Marsh</b> · Child · living · agrees · <span class="tg">Not notified yet</span></div><div class="hr"><b>Tanya Marsh-Reed</b> · Child · living · <span class="tg">Not notified yet</span></div><label class="fl hl ck">${B(5)}<span class="cbx"></span><span class="lb">This list has been double-checked and is complete</span></label>`, FIC)),
  right: ROOM([`Add one person at a time. We will do that on the next slides.`, `Prints the sworn affidavit from the heirs you list. The notary signing comes later.`, `Prints the certified mail envelopes for everyone who needs notice.`, `Each person shows as a row: relationship, living or not, and notice status.`, `Tick this <b>only</b> after a second person has checked the list.`]),
  say: `Now the heirs card. This is the list of everyone who may have a share. Number one, add a person. We will do that on the next slides. Number two prints the affidavit of heirship, the sworn statement a notary will see. Number three prints all the certified mail envelopes. Number four, each person shows as a row, with the relationship, whether they are living, and where their notice stands. Number five, the double check box. Tick it only after a second person has checked the list, because a missing heir is one of the most expensive mistakes in a case.` });

add({ part: "Heirs", h: `Add a person: <span class="lead">name, relationship, living.</span>`, left: FRAME(CARD("Add a person", `${G2(F(1, "Full name", "Marcus Andre Marsh"), SEL(2, "How they are related to the owner who died", "Child"))}${G2(SEL(3, "Living?", "Living"), F(4, "Phone", "312-555-0101"))}`, FIC)),
  right: ROOM([`Their full legal name, as on their ID.`, `How they are related to her. Child, spouse, grandchild of a child who died, parent, sibling, and so on.`, `Living, died, or not known.`, `A phone number, so you can reach them. A call is fine for staying in touch, but it never counts as legal notice.`]),
  say: `Here is the add a person form. Number one, their full legal name as it appears on their identification. Number two, how they are related to the owner who died. For her children, choose child. The list also covers a spouse, a grandchild of a child who has died, a parent, a sibling and others. Number three, whether they are living, died, or it is not known. Number four, a phone number. A phone call is fine for staying in touch, but it never counts as legal notice. Our notices go by certified mail only.` });

add({ part: "Heirs", h: `Address, email, <span class="gold">and former names.</span>`, left: FRAME(CARD("Add a person", `${F(1, "Mailing address (needed to send the court notice)", "100 N Example St, Apt 4, Chicago, IL 60601")}${F(2, "Email", "marcus@example.org")}${F(3, "Former names (maiden or other names used)", "")}`, FIC)),
  right: ROOM([`The address where certified mail will actually be received. Get it exact. This is the most common place for errors.`, `An email, for staying in touch.`, `Maiden names and other names, so the records line up. Blank if none.`]),
  say: `Still on the same form. Number one, the mailing address. This is the address the court notice will be mailed to, so it has to be a place where certified mail will actually be received. Get it exact, with the apartment number. This is the most common place for errors. Number two, an email address, for staying in touch. Number three, former names, such as a maiden name or any other name the person has used, so that the records line up. Leave it blank if there are none.` });

add({ part: "Heirs", h: `Who is whose child, <span class="lead">and the share.</span>`, left: FRAME(CARD("Add a person", `${G2(F(1, "Child of (for a grandchild, niece or nephew: the parent's name as listed here)", ""), F(2, "Share of the property, if known (for example 1/4)", "1/4"))}`, FIC)),
  right: ROOM([`Only for a grandchild, niece or nephew: the name of their parent, as listed in this same box. For Delia's own children, leave it blank.`, `The share, if the family or the court already knows it. Four equal children would each be one quarter. If you are not sure, leave it blank. Counsel and the court decide shares.`]),
  say: `Two more fields. Number one, child of. This is only for a grandchild, a niece or a nephew. Type the name of their parent, exactly as listed in this same box. For Delia's own children, leave it blank. Number two, the share of the property, if it is known. With no will and four children and no spouse, each child would commonly hold one quarter, but you only fill this in if you know. If you are not sure, leave it blank. Counsel and the court decide shares, not this page.` });

add({ part: "Heirs", h: `Four questions that <span class="gold">drive the case.</span>`, left: FRAME(CARD("Add a person", `${G2(SEL(1, "An adult able to act for themselves?", "Yes"), SEL(2, "Alive when the owner died?", "Yes"))}${G2(SEL(3, "Agrees to the proposed administrator?", "Yes"), SEL(4, "Available to sign a waiver once the petition is filed?", "Yes"))}`, FIC)),
  right: ROOM([`A minor, or someone with a disability or guardian, is <b>not</b> able to act for themselves. Choose No and add a note.`, `Alive when she died. Someone who died before her may leave their own children a share.`, `Ask. Get a written yes or no and keep it. Never answer for someone.`, `Can they sign a waiver of notice later? It cannot be signed until the petition is filed.`]),
  say: `Now four questions that drive the case. Number one, is the person an adult able to act for themselves. A minor, or someone with a disability or a guardian, is not, so choose no and add a note. Number two, were they alive when the owner died. A child who died before her may leave their own children a share. Number three, do they agree to the proposed administrator. Ask them, get a written yes or no, and keep it. Never answer for someone else. Number four, can they sign a waiver of notice later. A waiver cannot be signed until the petition has been filed.` });

add({ part: "Heirs", h: `A note, then <span class="lead">save the person.</span>`, left: FRAME(CARD("Add a person", `${F(1, "Note (for example: half-sibling, lives out of state, minor, mother of the owner)", "Oldest son. Proposed administrator.")}<div class="rw">${BTN(2, "Save person", "pri")}${BTN(3, "Cancel")}</div>`, FIC)),
  right: ROOM([`Anything that will help counsel: half-sibling, out of state, minor, hard to reach.`, `<b>Save person</b> adds them to the list.`, `Cancel throws away what you typed.`]),
  say: `Last on the form. Number one, a note. Put anything here that will help counsel: a half sibling, someone out of state, a minor, someone hard to reach. Number two, save person adds them to the list. Number three, cancel throws away what you typed. Then repeat the form for every child. Our practice family has four, so we would add Marcus, Tanya, Andre and Renee. The page shows how many are listed so far in the steps below.` });

add({ part: "Heirs", h: `Tracking each notice, <span class="gold">one person at a time.</span>`, left: FRAME(CARD("Heirs and others who may have a share", `<div class="hr hl">${B(1)}<b>Renee Holloway</b> · Child · living · lives out of state</div><div class="rw">${B(2)}<span class="in hl">Certified mail number</span>${B(3)}<span class="in sl hl">Certified mail sent<b>▾</b></span></div><p class="mt hl2">${B(4)}Warning: no mailing address for 1 person. Notice cannot be sent.</p>`, FIC)),
  right: ROOM([`Each person is a row. Open it to change or add details.`, `When you mail by certified mail, type the tracking number here. Keep the green card or the tracking printout.`, `Set the status: not notified, certified mail sent, signed a waiver, came to the hearing, or address unknown and published.`, `The warnings tell you who has no address, who has not been notified, and what is missing. Fix them before you print the packet.`]),
  say: `Once the case moves forward, the same heirs card tracks every notice. Number one, each person is a row. Open it to change details. Number two, when you mail a notice by certified mail, type the tracking number here, and keep the green card or the tracking printout. Number three, set the status: not notified, certified mail sent, signed a waiver, came to the hearing in person, or address unknown and published. Number four, the warnings. The page tells you who has no address, who has not been notified, and what is missing. Fix them before you print the packet.` });

// ---- PART 5: the guided steps --------------------------------------------------------------------------------------
add({ part: "The steps", h: `Every step has the <span class="lead">same three controls.</span>`, left: FRAME(STEP("Confirm who owns the property on record", "The recorded deed shows who holds title. The deed owner is the person named there, not whoever lives in the home or pays the taxes.", { n: "1.", sN: 1, dN: 2, nN: 3 })),
  right: ROOM([`<b>Status</b>: to do, in progress, done, or not needed. Done adds the date automatically.`, `<b>Target date</b>: when you plan to finish. Dates appear in the calendar and trigger reminder emails.`, `<b>Note</b>: the case number, document number, date, or who you told. Keep the note short and factual.`]),
  say: `Now the guided steps. Every step has the same three controls. Number one, the status. Choose to do, in progress, done, or not needed. When you choose done, the page stamps today's date. Number two, a target date. This is when you plan to finish. Dates appear in your calendar and trigger reminder emails. Number three, a note. Write the case number, the document number, the date, or who you told. Keep it short and factual. A step is never marked done until the evidence is in.` });

add({ part: "The steps", h: `Step: confirm <span class="gold">who owns it.</span>`, left: FRAME(STEP("Confirm who owns the property on record", "The recorded deed shows who holds title: Warranty Deed, Doc 0000000000 (example). The deed owner is the person named there, not whoever lives in the home or pays the taxes.", { n: "1.", status: "Done", due: "04/10/2026", note: "Warranty deed, Doc 0000000000, Delia A. Marsh, sole owner." })),
  right: ROOM([`Open the recorded deed from the Clerk's recordings. The owner is whoever the deed names.`, `Write the document number in the note.`, `If the deed names someone else, or two people, stop and tell counsel. That changes the case.`]),
  say: `The first step is to confirm who owns the property on record. Find the recorded deed. The owner is the person the deed names, not whoever lives in the house or pays the taxes. Write the document number in the note. In our example, the warranty deed shows Delia as sole owner. If the deed names someone else, or two people, stop and tell counsel, because that changes the whole case.` });

add({ part: "The steps", h: `Step: search the recorder, <span class="lead">and the first question.</span>`, left: FRAME(STEP("Search the recorder by P I N for anything recorded after that deed", "Search every parcel number. Record any deed, lien, mortgage or Transfer on Death Instrument that was recorded after the deed that put her on title.", { n: "2.", decN: 1, dec: { q: "Did the owner record a Transfer on Death Instrument?", c: ["Yes, one was recorded", "No, none was recorded"], pick: 1 }, status: "Done", sN: 2 })),
  right: ROOM([`Search the Clerk's recordings <b>for each P I N</b>. Record anything found in the Title search card.`, `The answer decides the path. A recorded Transfer on Death Instrument, called a T O D I, can pass the property without probate.`, `Choose honestly. Do not choose no because you did not look.`]),
  say: `Step two is a search. Search the recorder for each parcel number, and write down anything recorded after the deed that put her on title, such as a deed, a lien, a mortgage or a transfer on death instrument. Number one is the first question that changes the path. Did the owner record a transfer on death instrument, called a T O D I. If one was recorded, the property may pass without probate. If none, choose no. Choose honestly. Do not choose no because you did not look. Number two, mark the step done once you have searched every parcel.` });

add({ part: "The steps", h: `If a T O D I was recorded.`, body: `<div class="grid2"><div class="box top"><h3>Review it</h3><p class="small">For <b>each parcel</b>, confirm the instrument covers it, names the right beneficiaries, and was recorded before her death. A T O D I on one parcel says nothing about another.</p></div><div class="box top"><h3>Record the death affidavit</h3><p class="small">A beneficiary may file a notice of death affidavit with the Clerk's Recordings office to confirm title. It is signed before a notary. Filing it is not a condition of the transfer.</p></div></div><div class="note"><b>Then:</b> write the recorded document number in the note and go straight to the closing steps. Counsel still checks anything outside the instrument.</div>`,
  say: `If a transfer on death instrument was recorded, two steps appear. First, review it. For each parcel, confirm the instrument covers it, names the right beneficiaries, and was recorded before her death. An instrument on one parcel says nothing about another. Second, a beneficiary may file a notice of death affidavit with the Clerk's recordings office to confirm title. It is signed before a notary, and filing it is not a condition of the transfer. Write the recorded document number in the note, then go to the closing steps.` });

add({ part: "The steps", h: `Step: certified copies <span class="gold">of the death certificate.</span>`, left: FRAME(STEP("Get certified copies of the death certificate", "Certified means issued by the record custodian; a notary cannot turn a photocopy into a certified record. The posted form lists $17 for the first copy and $6 for each additional copy. Start with 2 or 3 copies.", { n: "3.", links: ["Cook County death certificates", "Death record request form"], note: "Ordered 3 copies on 03/20/2026, received 03/30/2026." })),
  right: ROOM([`<b>Certified</b> means issued by the record office. A photocopy is not enough.`, `Ask the funeral home which registrar holds the record. Call first to confirm hours, ID and who may request.`, `Start with two or three copies. The bank, the court and the title company may each want one.`, `Upload the certificate in the death certificate box and the details fill in.`]),
  say: `The next step is certified copies of the death certificate. Certified means issued by the record office. A notary cannot turn a photocopy into a certified record. Ask the funeral home which registrar holds the record, and call first to confirm hours, identification and who may request it. The posted form lists seventeen dollars for the first copy and six dollars for each extra copy ordered together. Start with two or three copies, because the bank, the court and the title company may each want one. Then upload the certificate in the death certificate box.` });

add({ part: "The steps", h: `Step: the heir confirms <span class="lead">the name for the deed.</span>`, left: FRAME(STEP("The heir confirms the name to use on the deed", "Records show more than one version of the heir's name. The heir picks the one that is correct, or types or speaks it. The deed must carry the legal name, so check it against ID.", { n: "4.", note: "" }) + CARD("Which name is correct?", `<span class="ch on">${B(1)}Marcus Andre Marsh</span><span class="ch">Marcus A. Marsh</span><span class="ch">Marcus Marsh</span><span class="ch">${B(2)}Type a different name</span>`)),
  right: ROOM([`Pick the version of the name that matches the heir's government ID.`, `Or type it. The legal name matters because the deed will carry it.`, `Mark the step <b>Done</b> only after the heir has checked the name against their ID.`]),
  say: `Step four. Records often show more than one version of an heir's name. Number one, the heir picks the version that is correct. Number two, or types it, if none of them is right. The deed must carry the legal name, so check it against a government identification. Mark the step done only after the heir has checked it against their I D. A small spelling mistake now can cost real money to fix on a recorded deed later.` });

add({ part: "The steps", h: `Step: is there <span class="gold">a will?</span>`, left: FRAME(STEP("Find out whether the owner left a will", "With no recorded T O D I the property may be part of her estate. Ask the family whether a will exists and who holds the original. What you choose decides the steps that follow.", { n: "5.", decN: 1, dec: { q: "Is there a will?", c: ["Yes, there is a will", "No will"], pick: 1 }, status: "Done", nN: 2, note: "Asked all four children. No will found. Searched house, bank box, attorney." })),
  right: ROOM([`Ask every child. Look where a will is usually kept: the house, a safe deposit box, her lawyer, the funeral home.`, `Choose yes or no. This changes the steps. With a will, you add will steps. With no will, you add the heirship steps.`, `Write where you looked in the note, and in the Search log card.`]),
  say: `Step five, find out whether the owner left a will. Ask every child. Look where a will is usually kept: the house, a safe deposit box, her lawyer, the funeral home. Number one, choose yes or no. This decides the steps that follow. With a will, you get the will steps. With no will, you get the heirship steps. Number two, write where you looked in the note, and in the search log card, so counsel can see the search was really done. If a will turns up later, tell counsel at once.` });

add({ part: "The steps", h: `Step: gather what the court <span class="lead">will ask for.</span>`, left: FRAME(STEP("Gather what the court will ask for", "A certified death certificate, a list of every heir (use the Heirs box above: 4 listed so far) with full names, addresses and how each is related, and a rough value of the estate. With no will, a surviving spouse or other children may also have a share by law.", { n: "6.", status: "In progress" })),
  right: ROOM([`The page counts the heirs you have listed so far. It should match the family.`, `A rough value of the estate: the property plus anything else she left.`, `With no will, check there is no spouse and no other child anywhere. If there is, they have a share.`]),
  say: `Step six, gather what the court will ask for. A certified death certificate, a list of every heir with full names, addresses and how each one is related, and a rough value of the estate. The step counts the heirs you have listed so far, which should match the family. With no will, check carefully that there is no surviving spouse and no other child anywhere. If there is one, they have a share by law, and leaving them out can undo the whole case later.` });

add({ part: "The steps", h: `Step: contact every child, <span class="gold">in writing.</span>`, left: FRAME(STEP("Contact every child: collect names, addresses and agreement", "Reach each child. For each one, fill in the Heirs box: full legal name and former names, mailing address, phone and email, whether they are an adult, whether they were alive when the owner died, whether they agree to the proposed administrator, and whether they can sign a waiver. Ask for a written yes or no. 4 listed so far.", { n: "7.", status: "In progress" })),
  right: ROOM([`Reach <b>each</b> child. Use the heirs card to record what they say.`, `Ask for a <b>written</b> yes or no on the administrator. A text message you keep is fine. Save it.`, `If anyone will not agree or cannot be reached, write why and plan the thirty day certified notice for them.`]),
  say: `Step seven, contact every child. Reach each one and use the heirs card to record what they tell you. Ask for a written yes or no about the proposed administrator, and keep it. A text message you save is fine. If anyone will not agree, or cannot be reached, write down why in the note, and plan the certified mail notice for them, which must go out at least thirty days before the hearing. This step is where family conversations matter most. Take your time and be kind.` });

add({ part: "The steps", h: `Step: taxes, debts, <span class="lead">and value.</span>`, left: FRAME(STEP("Find the property's taxes, debts and value", "For each P I N: look up the tax bills and any unpaid years at the Treasurer, and the property details at the Assessor. Collect mortgage statements, recorded releases and any tax-sale notices. Get a supported market value and write the date it applies to.", { n: "8.", links: ["Cook County Treasurer", "Cook County Assessor", "Recorder search"] })),
  right: ROOM([`Look up <b>each</b> parcel at the Treasurer. Do not assume one covers the other.`, `Collect mortgage or equity loan statements and any payoff amounts.`, `Get a supported value: comparable sales, a broker's opinion or an appraisal. Write the date it applies to. Do not use assessed value.`, `If it is rented, list each tenant, the rent, any arrears and the security deposits.`]),
  say: `Step eight, the property's taxes, debts and value. For each parcel number, look up the tax bills and any unpaid years at the Treasurer, and the property details at the Assessor. Do not assume one parcel covers the other. Collect mortgage or equity loan statements, recorded releases, and any tax sale or foreclosure notices. Get a supported market value from comparable sales, a broker's opinion or an appraisal, and write the date it applies to. Do not use the assessed value. If the property is rented, list each tenant, the rent, any arrears, and the security deposits. A deposit held is owed to the tenant.` });

add({ part: "The steps", h: `Step: accounts, vehicles, <span class="gold">and everything else.</span>`, left: FRAME(STEP("Find the personal estate: accounts, vehicles and other assets", "List cash and accounts in her name alone, vehicles and other property. Separate what passes outside probate: joint accounts, life insurance or accounts with a named beneficiary, trust assets. Search for unclaimed property under her name.", { n: "9.", links: ["Illinois I-Cash"] })),
  right: ROOM([`List accounts in <b>her name alone</b>. Use the statement for the month she died.`, `Set aside what passes outside probate: joint accounts, accounts with a beneficiary, insurance. Tell counsel.`, `Search the state's unclaimed property site under her name and address.`, `Look for a final paycheck, a pension, a tax refund, or anything owed to her.`]),
  say: `Step nine, the personal estate. List cash and accounts in her name alone, using the statement for the month she died. List vehicles and any other property. Then set aside what passes outside probate, such as joint accounts, life insurance or accounts with a named beneficiary, and trust assets. Tell counsel about those, and counsel decides what is in the estate. Search the state's unclaimed property site under her name and address. And look for a final paycheck, a pension, a tax refund, or anything else owed to her.` });

add({ part: "The steps", h: `Step: find every creditor, <span class="lead">and list each one.</span>`, left: FRAME(STEP("Find every creditor and add each one to the Creditors box", "Creditors are separate from heirs and must be told. Look in her mail, the funeral invoice, medical bills, the mortgage lender, tax bills, credit card and utility accounts. Add the name, address, amount and a note to the Creditors box. 3 creditors listed so far.", { n: "10.", links: ["Treasurer", "Illinois HFS estate recovery", "Illinois Department of Revenue"] })),
  right: ROOM([`Go through her mail and log <b>every</b> bill. Collect it at the property.`, `Funeral invoice, hospital and doctor bills, lender, taxes, cards, utilities.`, `Did she receive Medicaid? That triggers a review of a possible state claim. It is not an automatic debt.`, `Add each creditor in the Creditors box. Only the last four digits of any account number.`]),
  say: `Step ten, find every creditor. Creditors are separate from heirs, and they must be told. The debts do not disappear because only the children inherit. Look in her mail, and log every bill. Check the funeral invoice, medical and hospital bills, the mortgage lender, tax bills, and credit card and utility accounts. Ask whether she received Medicaid. That triggers a review of a possible state claim, but it is not an automatic debt. Add each creditor in the creditors box, with only the last four digits of any account number.` });

add({ part: "The steps", h: `Step: choose the route, <span class="gold">with counsel.</span>`, left: FRAME(STEP("Choose the route with counsel (it is not assumed)", "Full probate is one possible outcome, not the starting assumption. The Route evaluation box shows what is still missing. Then choose with counsel. Until a route is chosen, the filing steps stay hidden.", { n: "11.", decN: 1, dec: { q: "Which route will be used for this property?", c: ["Not decided yet", "Full administration, independent", "Full administration, supervised", "Heirship determination only", "Summary administration", "No estate case: title company accepts heirship evidence", "A title or co-ownership dispute"], pick: 0 } })),
  right: ROOM([`Pick a route from the list. <b>Not decided yet</b> is a perfectly good answer while you gather facts.`, `The filing steps stay hidden until you choose a route that needs them.`, `The choice is made <b>with counsel</b>. Do not pick one alone.`]),
  say: `Step eleven is the choice of route, and it is not assumed. Full probate is one possible outcome, not the starting point. The list offers independent administration, supervised administration, a heirship order only, summary administration, a route where the title company accepts the paperwork, and a title dispute that counsel must resolve. Number one, not decided yet is a perfectly good answer while you gather facts. The filing steps stay hidden until you choose a route that needs them. Make this choice with counsel, never alone.` });

add({ part: "The cards", h: `Route evaluation: <span class="lead">what did she own?</span>`, left: FRAME(CARD("Route evaluation", `${SEL(1, "20-00-000-001-0000", "She owned it alone")}${SEL(1, "20-00-000-002-0000", "Not yet examined")}${G2(SEL(2, "What should the property end up as?", "One person owns it"), SEL(3, "Does anything need a representative's authority (bank account, claim, sale)?", "Not known yet"))}${SEL(4, "Is any heir missing, uncooperative or disputing, or is the title disputed?", "No")}${F(5, "Cost and delay of each viable route", "", { area: true, ph: "Filing fees, bond, publication, title charges, recording..." })}${G2(F(6, "Route approved by (counsel or reviewer)", ""), F(7, "Date approved", "", { ph: "mm/dd/yyyy" }))}`, FIC)),
  right: ROOM([`One drop-down <b>per parcel</b>. What did she actually own in each one?`, `What should the property end up as: shared, one owner, sold, or refinanced.`, `Does anything need a representative's power, such as a bank account, a claim or a sale?`, `Any missing, uncooperative or disputing heir, or a title dispute?`, `Estimate the cost and delay of each route. Counsel will refine it.`, `Who approved the route.`, `And the date.`]),
  say: `The route evaluation card helps counsel choose. Number one, one drop down for each parcel. What did she actually own in each one? Number two, what should the property end up as: shared among the heirs, owned by one person, sold, or refinanced. Number three, does anything need a representative's authority, such as a bank account, a claim or a sale. Number four, is any heir missing, uncooperative or disputing, or is the title disputed. Number five, estimate the cost and delay of each route. Counsel will refine it. Numbers six and seven record who approved the route and when. A box underneath shows what is still missing.` });

add({ part: "The cards", h: `Title search card: <span class="gold">what the recorder shows.</span>`, left: FRAME(CARD("Title search at the recorder", `${G2(F(1, "Date searched", "04/05/2026"), F(2, "The Clerk's index ran through", "04/03/2026"))}${F(3, "P I Ns searched (list every one)", "20-00-000-001-0000; 20-00-000-002-0000")}${F(4, "Owner of record: the recorded document that put her on title", "Warranty Deed, Doc 0000000000")}<div class="hr hl">${B(5)}Doc 0000000001 · Mortgage · recorded 06/12/2009 · Released 2019</div><div class="rw">${BTN(6, "+ Add a document found", "pri")}</div>`, FIC)),
  right: ROOM([`The day you searched.`, `The date the Clerk's index runs through. Recent filings may not show yet.`, `Every parcel you searched.`, `The recorded document that made her the owner.`, `Each document found: number, type, date recorded, parties and a note.`, `Add one row per document. Liens and mortgages matter.`]),
  say: `The title search card keeps a record of what the recorder shows. Number one, the date you searched. Number two, the date the Clerk's index runs through. Very recent filings may not show yet. Number three, every parcel you searched. Number four, the recorded document that made her the owner. Number five, each document you found, with its number, type, date recorded, the parties, and a note on whether it was released. Number six, add one row per document found. Liens and mortgages matter, because they stay with the property.` });

add({ part: "The cards", h: `Check the facts <span class="lead">the plan depends on.</span>`, left: FRAME(CARD("Check the facts this plan depends on", `${CHK(1, "The owner had no surviving spouse or civil union partner when she died")}${CHK(2, "Everyone in the Heirs box is her legally recognized child and survived her")}${CHK(3, "Every child listed is an adult and can act for themselves")}${CHK(4, "No will, trust transfer, later deed or T O D I changes the route")}${CHK(5, "Title was held by her alone", false)}${CHK(6, "Counsel has confirmed where the case must be filed", false)}`, "The plan only works if these are true. If any is not, tell counsel before anything is filed.")),
  right: ROOM([`Tick only what you have <b>checked</b>, not what you assume.`, `No other child, no child who died, no parentage question.`, `No minor, no guardian.`, `No will, trust, later deed or T O D I.`, `Sole title, not joint tenancy, a trust or a land trust. Those can mean no probate is needed.`, `Counsel confirms where to file, especially if she did not live in Cook County.`]),
  say: `This card lists the facts the plan depends on. Tick a box only when you have checked it, not when you assume it. Number one, no surviving spouse. Number two, everyone in the heirs box is her legally recognized child and survived her. Number three, every child listed is an adult and can act for themselves. Number four, no will, trust transfer, later deed or transfer on death instrument changes the route. Number five, title was held by her alone, not as joint tenants, in a trust, or a land trust. Number six, counsel has confirmed where the case must be filed. If any box cannot be ticked, tell counsel before anything is filed.` });

add({ part: "The cards", h: `Name check and <span class="gold">search log.</span>`, left: FRAME(CARD("Name check", `${F(1, "How the names differ and why", "The deed says Delia A. Marsh; the death certificate says Delia Ann Marsh. Same person.", { area: true })}${F(2, "Supporting records on hand", "Driver's license copy, 1998 marriage license", { area: true })}`) + CARD("Search log: will and earlier probate case", `${G2(F(3, "Will search: places looked and people asked", "House, bank, her attorney, funeral home"), F(4, "Date", "04/02/2026"))}${G2(F(5, "Earlier probate case search", "Delia Marsh, Cook County Probate"), F(6, "Date", "04/02/2026"))}${F(7, "Result", "Nothing found")}`)),
  right: ROOM([`If her name differs between the deed, the certificate and other records, explain how and why.`, `List the records that connect them: a marriage license, a name change order.`, `Where you looked for a will, and who you asked.`, `The date of the will search.`, `Whether you searched for an earlier probate case and where.`, `The date.`, `The result: nothing found, or what was found.`]),
  say: `Two small cards that protect the case. The name check. Number one, if her name differs between the deed, the certificate and other records, explain how and why. Number two, list the records that connect the names, such as a marriage license or a name change order. Then the search log. Number three, where you looked for a will and who you asked. Number four, the date. Number five, whether you searched for an earlier probate case, and where. Number six, the date. Number seven, the result, nothing found or what was found. Counsel reads this to know the search was really done.` });

add({ part: "The cards", h: `Proposed administrator: <span class="lead">eligibility.</span>`, left: FRAME(CARD("Proposed administrator: eligibility", `${G2(F(1, "Full legal name", "Marcus Andre Marsh"), F(2, "Relationship to the owner", "Son"))}${F(3, "Street address, city, state, ZIP", "100 N Example St, Apt 4, Chicago, IL 60601")}${G2(F(4, "Phone and email", "312-555-0101; marcus@example.org"), SEL(5, "Residence", "Illinois"))}${CHK(6, "At least 18 years old")}${CHK(6, "A resident of the United States")}${CHK(6, "Not of unsound mind or adjudicated disabled")}${CHK(6, "No felony conviction (or disclosed to counsel)")}`, FIC)),
  right: ROOM([`The person the family proposes to serve, by full legal name.`, `How they are related to Delia.`, `Their address.`, `Phone and email.`, `Where they live. Someone outside Illinois needs an agent arrangement; the page shows a box for it.`, `Four checks the court asks about. Tick each one honestly. If one is not true, tell counsel.`]),
  say: `The proposed administrator card. This is the person the family proposes to serve. Number one, their full legal name. Number two, how they are related. Number three, their address. Number four, phone and email. Number five, where they live. Someone who lives outside Illinois needs an agent arrangement, and the page shows a box for it. Number six is four checks the court asks about: at least eighteen, a resident of the United States, not of unsound mind or adjudicated disabled, and no felony conviction, or a conviction disclosed to counsel. Tick each one honestly. If one is not true, tell counsel.` });

add({ part: "The cards", h: `Assets, debts and <span class="gold">the property.</span>`, left: FRAME(CARD("Assets, debts and the property", `${G2(F(1, "Real estate: approximate market value ($)", "380,000"), F(2, "Value as of (date)", "04/01/2026"))}${F(3, "How the value was figured", "Two comparable sales and a broker opinion")}${G2(F(4, "Personal estate ($)", "6,500"), F(5, "Gross annual real estate income ($)", "21,600"))}${SEL(6, "Will the administrator take possession and collect the rent?", "Yes")}${F(7, "Tenants and occupants", "Unit 1: J. Doe, $900/month, no arrears, deposit $900 held by Delia.", { area: true })}${F(8, "Mortgage, taxes owed, liens", "No mortgage. 2025 second installment unpaid.", { area: true })}`, "Estimates are fine; exact balances can wait for the letters.")),
  right: ROOM([`An approximate market value. <b>Not</b> the assessed value and not the deed's ten dollars.`, `The date the value applies to.`, `How you figured it.`, `Cash and sole name accounts, vehicles, other.`, `Gross yearly rent: monthly rent times twelve, plus other income. The bond is sized from this.`, `Will the administrator collect the rent?`, `Tenants: names, rent, arrears, deposits and who holds them.`, `Mortgage, taxes owed, liens, tax sale or foreclosure notices.`]),
  say: `The assets card. The court asks for approximate figures, and the bond is sized from them. Estimates are fine. Number one, the approximate market value of the real estate. Not the assessed value, and not the deed's ten dollar consideration. Number two, the date that value applies to. Number three, how you figured it. Number four, the personal estate: cash, sole name accounts, vehicles. Number five, the gross yearly rent, which is monthly rent times twelve, plus other income. Number six, will the administrator collect the rent. Number seven, tenants, with rent, arrears and deposits. Number eight, mortgages, taxes owed and liens. Below these are fields for insurance, urgent deadlines and joint or beneficiary assets.` });

add({ part: "The cards", h: `Known creditors and <span class="lead">the Medicaid check.</span>`, left: FRAME(CARD("Known creditors", `${CHK(1, "No creditors are known", false)}${SEL(2, "Did she receive Medicaid benefits?", "No")}<div class="hr hl">${B(3)}<b>Example Hospital Billing</b> · $4,200 · mailed 05/02/2026 · tracking on file</div>${G2(F(4, "Creditor name", ""), F(4, "Amount owed (if known)", ""))}${F(5, "Mailing address", "")}${F(6, "Note (account number last four digits only)", "")}<div class="rw">${BTN(7, "+ Add a creditor", "pri")}</div>`, FIC)),
  right: ROOM([`Tick only if you have searched and truly know of none.`, `If she received Medicaid, the state may review a claim. It is a review, not an automatic debt. Record the inquiry and the response.`, `Each creditor is a row with the mailing date and certified mail number.`, `Name and amount.`, `Address, for the certified mail.`, `A note. <b>Only the last four digits</b> of any account.`, `Add it. Do this for every creditor you find.`]),
  say: `The known creditors card. Number one, tick this only if you have searched and truly know of none. Number two, did she receive Medicaid. If yes, the state may review a possible claim against the estate. It is a review, not an automatic debt, and the page records the inquiry date and the response. Number three, each creditor is a row, with the mailing date and the certified mail number. To add one, number four, the name and amount, number five, the mailing address, which is needed for the certified mail, and number six, a note, with only the last four digits of any account number. Number seven, press add a creditor. Do this for every creditor you find.` });

add({ part: "The cards", h: `Documents: <span class="gold">three folders.</span>`, left: FRAME(CARD("Documents", `<div class="rw">${BTN(1, "Add any missing standard documents for this route")}</div><div class="hr hl">${B(2)}<b>A · 01 Certified death certificate</b> · Ready</div><div class="hr hl">${B(3)}<b>B · Petition for Letters of Administration (CCP 0302)</b> · In progress · <span class="tg">Upload scan</span></div><div class="hr"><b>C · Death certificate original (private)</b> · Ready</div>`, FIC)),
  right: ROOM([`Press this to load the standard documents for your chosen route.`, `Each document has a status: not started, requested, in progress, ready, signed, filed.`, `Upload the scan and note where the paper original is kept.`, `Folder A, B and C are the way counsel wants them. Name the final PDFs in order: zero one, zero two, and so on.`]),
  say: `The documents card keeps three folders, the way counsel will want them. Number one, press the button to add the standard documents for your chosen route. Number two, each document has a status: not started, requested, in progress, ready, signed or filed. Number three, upload the scan, and note where the paper original is kept. Folder A is for what you gather, folder B for what counsel files, and folder C for private evidence that stays with you. Name the final P D Fs in order, zero one, zero two and so on, so counsel can read them in sequence.` });

add({ part: "The cards", h: `Timeline and <span class="lead">deadlines.</span>`, left: FRAME(CARD("Timeline and deadlines", `${G2(F(1, "Date of the court hearing", "09/15/2026"), F(2, "Date of the court's order appointing the representative", ""))}${G2(F(3, "Date the letters of office were issued", ""), F(4, "Date of the first newspaper notice to creditors", ""))}<div class="hr hl">${B(5)}Mail the petition by certified mail to the heirs who rank equal or higher. Due 08/16/2026.</div>`, "Enter a date and the page works out the rest. These are estimates; counsel confirms the ones that count.")),
  right: ROOM([`Enter the hearing date when the court gives it.`, `Then the date of the order appointing the representative.`, `The date the letters of office issued.`, `The date of the first newspaper notice to creditors.`, `The page works out deadlines from these, cites the law, and adds them to What's next with reminder emails.`]),
  say: `The timeline card. You only enter court dates here, and the page works out the rest. Number one, the date of the court hearing, when the court gives it. Number two, the date of the order appointing the representative. Number three, the date the letters of office were issued. Number four, the date of the first newspaper notice to creditors. Number five, the page then works out the deadlines, such as mailing the petition at least thirty days before the hearing, cites the law, adds them to what's next, and sends reminder emails seven days before, three days before, one day before, on the day, and if overdue. These are estimates. Counsel confirms the ones that count.` });

// ---- PART 6: more steps -------------------------------------------------------------------------------------------
add({ part: "The steps", h: `If you chose a route <span class="gold">other than full probate.</span>`, body: `<div class="grid2">
  <div class="box top"><h3>Heirship only</h3><p class="small">A court order that names the heirs. It does not appoint anyone, pay a lien, or settle a dispute. Get the title company's written requirements first.</p></div>
  <div class="box top"><h3>Summary administration</h3><p class="small">Only if the gross estate is $100,000 or less and <b>every</b> heir consents in writing, with other conditions. The page tests the limit against your Assets card.</p></div>
  <div class="box top"><h3>No estate case</h3><p class="small">Ask the title company in writing whether it will insure the transaction, and what it requires. Record the answer.</p></div>
  <div class="box top"><h3>A dispute</h3><p class="small">Competing deeds or disagreements are not solved by an inheritance filing. Take the evidence to counsel.</p></div></div>`,
  say: `If you chose a route other than full probate, a different step appears. For heirship only, the court order names the heirs, but it does not appoint anyone, pay a lien or settle a dispute, so get the title company's written requirements first. For summary administration, the gross estate must be one hundred thousand dollars or less and every heir must consent in writing, among other conditions, and the page tests the limit against your assets card. For no estate case, ask the title company in writing whether it will insure the transaction, and record the answer. For a dispute, take the evidence to counsel.` });

add({ part: "The steps", h: `If there is a will: <span class="lead">deliver it.</span>`, left: FRAME(STEP("Deliver the original will to the Clerk of the Circuit Court of Cook County (Probate Division)", "Illinois law requires whoever holds the will to file it with the Clerk immediately after the death. Filing the will itself has no fee. Write who held the original, and the date it was filed, in the note.", { n: "", links: ["755 ILCS 5/6-1", "Copy of Will (CCP 0317)"], note: "Original held by Tanya. Filed 04/08/2026." })),
  right: ROOM([`Whoever holds the original must file it with the Clerk right away. Holding it back is a crime.`, `Filing it has no fee.`, `Write who held it and the date filed in the note, and set the date in the Timeline card.`]),
  say: `If there is a will, the next step is to deliver the original to the Clerk of the Circuit Court. Illinois law requires whoever holds the will to file it immediately after the death, and holding a will back is a crime. Filing the will itself has no fee. Number one, write who held the original and the date it was filed in the note, and enter the date in the timeline card. A second will step lists what must be filed before the hearing, such as an affidavit attaching a copy.` });

add({ part: "The steps", h: `Step: who files the petition, <span class="gold">the plan and the fallback.</span>`, left: FRAME(STEP("Decide who files the petition: a lawyer (the plan) or the family (the fallback)", "The plan: the family finishes the preparation, takes the counsel packet to a free-help consultation, and the lawyer reviews and files it, or the family goes to the next consultation. The fallback, only if no lawyer accepts after the consultations: the family files in its own name as an heir seeking to serve.", { n: "", links: ["In re Estate of Mattson", "Clerk: Self-Represented Litigant Center", "Illinois Legal Aid: e-filing exemption"] })),
  right: ROOM([`The plan is that a lawyer files. In Cook County a non-lawyer cannot represent an estate.`, `The fallback is only after every consultation has said no. The judge may refuse it.`, `Before any filing, call the Probate Division or the Self-Represented Litigant Center, and write what you were told and by whom.`]),
  say: `This step decides who files the petition. The plan is that a lawyer reviews and files it. In Cook County, a court of appeals has held that a non lawyer cannot represent an estate, so we plan for a lawyer. The fallback is only for when no lawyer accepts after every consultation. Then the family may file in its own name, as an heir seeking to serve, knowing the judge may refuse it. Before any filing, call the Probate Division or the Self Represented Litigant Center, and write down what you were told and by whom.` });

add({ part: "The steps", h: `Step: choose the administrator, <span class="lead">then the petition.</span>`, left: FRAME(STEP("Decide who will serve as administrator", "Illinois sets an order of preference: a surviving spouse first, then the children or whoever they nominate, then grandchildren, parents, siblings and so on. Several children have equal rights, so the court chooses; the others may be asked to agree.", { n: "", links: ["755 ILCS 5/9-3"] }) + STEP("Prepare and sign the Petition for Letters of Administration", "The petition asks the court to declare the heirs and appoint the administrator. It lists every heir with a mailing address and the estate's approximate value. Get the current Cook County forms from the Clerk.", { n: "", links: ["CCP 0302", "CCP 0303", "CCP 0305", "CCP 0314", "CCP 0199"] })),
  right: ROOM([`The order of preference is set by law. Check it against the heirs card.`, `The petition is prepared from the facts you entered. Print the <b>petition worksheet</b> from the page.`, `Counsel reviews it. Only counsel certifies and files it.`, `Always use the <b>current</b> forms from the Clerk. Older copies online are out of date.`]),
  say: `Two steps come next. First, who will serve as administrator. Illinois sets an order of preference. A surviving spouse comes first, then the children or whoever they nominate, then grandchildren, parents and siblings. Several children have equal rights, so the court chooses, and the others may be asked to agree. Second, prepare the petition. It asks the court to declare the heirs and appoint the administrator, and lists every heir with a mailing address and the approximate value of the estate. Print the petition worksheet from the page. Counsel reviews it, and only counsel certifies and files it. Always use the current forms from the Clerk.` });

add({ part: "The steps", h: `Step: the affidavit of heirship, <span class="gold">sworn before a notary.</span>`, left: FRAME(STEP("Prepare the Affidavit of Heirship and have it sworn before a notary", "With no will, the court relies on a sworn statement from someone who knows the family: how they are related to the owner, the date and place of death, the owner's marriages and children and parents, and every heir, living or dead. It must match the Heirs box exactly.", { n: "", links: ["Court sample 1", "Court sample 2", "Order Declaring Heirship (CCP 0305)"] }) + CARD("Affidavit facts", `${G2(F(1, "Who is swearing", "Marcus Marsh"), F(2, "How they are related", "Son"))}<div class="rw">${BTN(3, "Print the affidavit of heirship", "pri")}</div>`)),
  right: ROOM([`The person who swears should know the family well. An adult child often does.`, `Their relationship to Delia.`, `Print it, check it against the court's samples, and take it to a notary. <b>Sign only in front of the notary.</b>`, `It must match the heirs card exactly: every heir, living or dead.`]),
  say: `With no will, the court relies on a sworn statement from someone who knows the family. That is the affidavit of heirship. Number one, who is swearing. It should be someone who knows the family well, and an adult child often does. Number two, their relationship to Delia. Number three, print the affidavit from the page, check it against the court's two sample forms, and take it to a notary. Sign only in front of the notary. It states the date and place of death, the owner's marriages, children and parents, and every heir, living or dead. It must match the heirs card exactly.` });

add({ part: "The steps", h: `Step: hand the case to <span class="lead">free legal help.</span>`, left: FRAME(STEP("Hand the completed case to free legal help (so no attorney is paid)", "The family does the work and hands counsel a finished case: here is our case, file it, or we go to the next scheduled consultation. Ask for the first appointment early. Print the counsel packet and bring it.", { n: "", links: ["Chicago Volunteer Legal Services: apply", "A Guide to Legal Services in Cook County"] }) + CARD("Consultations", `${G2(F(1, "With (lawyer or organization)", "Chicago Volunteer Legal Services"), F(2, "Consultation date", "06/10/2026"))}<div class="rw">${BTN(3, "Save consultation", "pri")}</div>`)),
  right: ROOM([`Log every call and every meeting: who, and what they said.`, `The date.`, `Save it. If the answer is no, move to the next contact. Free help depends on income and is screened.`]),
  say: `Now the step that gets the case in front of a lawyer. The family does the work and hands counsel a finished case, with one message: here is our case, file it, or we go to the next scheduled consultation. Ask for the first appointment early, because scheduling takes time. Then use the consultations log. Number one, who you spoke with. Number two, the date. Number three, save it. Write down what each contact says, and if the answer is no, move to the next one. Free help depends on income and is screened by the program.` });

add({ part: "The steps", h: `Step: the e-filing check, <span class="gold">cover sheet and redaction.</span>`, left: FRAME(STEP("Prepare the e-filing: cover sheet category, redaction check and the choice of route", "Cover sheet (CCP 0199): check one category. Redaction (Supreme Court Rule 138): do not file full Social Security numbers, driver's license numbers or financial account numbers. A public filing may show only the last four digits.", { n: "", links: ["CCP 0199", "Rule 138", "e-File Illinois"] })),
  right: ROOM([`The cover sheet category depends on the route and on whether there is a will. Counsel picks it.`, `<b>Redaction:</b> never file full Social Security, license or account numbers. The death certificate shows a full Social Security number, so counsel decides what is filed and in what redacted form.`, `The original death certificate stays in your private folder.`]),
  say: `Before filing, there is an e filing check. The cover sheet needs one category checked, and the category depends on the route and on whether there is a will. Counsel picks it. Then redaction. Under Illinois Supreme Court Rule one thirty eight, do not file full Social Security numbers, driver's license numbers, or financial account numbers. A public filing may show only the last four digits of a Social Security number. The death certificate shows the full number, so counsel decides what is filed and in what redacted form. The original stays in your private folder.` });

add({ part: "The steps", h: `Step: file, then <span class="lead">record the court details.</span>`, left: FRAME(STEP("File the petition with the Clerk of the Circuit Court of Cook County, Probate Division, and pay the filing fee", "Counsel files this electronically once they have accepted the case. The Clerk's Probate Division page lists the filing fee as $479. If you cannot pay, ask about a fee waiver.", { n: "", links: ["Probate Division", "Filing costs", "Fee waiver application"] }) + STEP("After filing: the assigned judge, the hearing date and the proposed orders", "The Clerk assigns a case number, judge, courtroom and calendar. The judge's standing order controls scheduling and how proposed orders are delivered.", { n: "", note: "Case 2026-P-000000 (example). Judge and calendar recorded." })),
  right: ROOM([`The lawyer files electronically. The fee is four hundred seventy-nine dollars. Ask about a fee waiver if you cannot pay.`, `Record the case number, judge, courtroom, calendar and hearing date. Enter the hearing date in the Timeline card.`, `Leave the judge's signature and the entry date blank on proposed orders.`]),
  say: `Once counsel has accepted the case and reviewed the packet, counsel files electronically. The Clerk's Probate Division page lists the filing fee as four hundred seventy-nine dollars. If you cannot pay, ask about a fee waiver. After filing, the Clerk assigns a case number, a judge, a courtroom and a calendar. Number one, the judge's standing order controls scheduling and how proposed orders are delivered, so read it. Number two, record the case number and details in the note, and enter the hearing date in the timeline card. Leave the judge's signature and entry date blank on any proposed order.` });

add({ part: "The steps", h: `Step: notify the heirs, <span class="gold">certified mail only.</span>`, left: FRAME(STEP("Notify the heirs in writing (by mail), and file proof of mailing", "We send every notice by certified mail, return receipt requested, and by nothing else. For each person, write the certified-mail number in the Heirs box, keep the green card or tracking printout, and file proof of mailing with the Clerk. 3 of 4 handled.", { n: "", links: ["755 ILCS 5/9-5", "Notice to Interested Parties (CCP 1004)", "Waiver of Notice (CCP 0303)"], dN: 2 })),
  right: ROOM([`<b>Certified mail only.</b> A call, text or email is not notice, though it is fine to tell people too.`, `At least thirty days before the hearing, mail the petition to anyone with an equal or better right to serve. After the order, within fourteen days, mail the petition and the order to every other heir.`, `If an address is unknown, publish a newspaper notice once a week for three weeks.`, `A waiver of notice cannot be signed before the petition is filed.`]),
  say: `This step is notice to the heirs, and our rule is simple: certified mail only. A phone call, text message or email does not count as notice, although it is fine to tell people too. For each person, type the certified mail number in the heirs card, keep the green card or tracking printout, and file proof of mailing with the Clerk. At least thirty days before the hearing, mail the petition to anyone with an equal or better right to serve. After the order, within fourteen days, mail the petition and the order to every other heir. If an address is unknown, publish a notice once a week for three weeks. A waiver of notice cannot be signed before the petition is filed.` });

add({ part: "The steps", h: `Step: the bond, <span class="lead">and the oath.</span>`, left: FRAME(STEP("Arrange the surety bond and sign the oath", "With no will, plan on a surety bond (CCP 0312). The other heirs agreeing is not a bond waiver. The representative signs the oath before a notary or the Clerk, and a licensed surety agent signs for the surety company.", { n: "", links: ["CCP 0312", "CCP 0313", "Cook County Rule 12"] }) + CARD("Assets (bond)", `${F(1, "Bond arrangement: surety agent, quote, premium and status", "Quote requested from ABC Surety (example)")}${CHK(2, "The surety has approved the bond and it is ready to sign", false)}`)),
  right: ROOM([`A bond is expected even if the other heirs agree, and even if a will waives it.`, `Get a quote from a surety agent. The premium is a separate cost: add it to the court costs.`, `Tick this only when the surety has approved it.`]),
  say: `Step: arrange the surety bond and sign the oath. A bond is expected even when the other heirs agree. Agreement among heirs is not a bond waiver. Even a will that waives bond does not waive it in Cook County. The representative signs the oath before a notary or the Clerk, and a licensed surety agent signs for the surety company. Number one, in the assets card, write the surety agent, the quote and the status. The premium is a separate cost, so add it to the court costs. Number two, tick the approval box only when the surety has actually approved the bond.` });

add({ part: "The steps", h: `Step: the hearing, <span class="gold">and the appointment.</span>`, left: FRAME(STEP("Attend the court hearing", "The judge reviews the petition and the list of heirs. A witness who knew the family may be asked to confirm the heirs under oath. Bring the death certificate.", { n: "" }) + STEP("The court appoints the administrator (letters of administration)", "The representative takes an oath and the Clerk issues the letters of office. Order several certified copies: the deed, the bank and the title company will each ask for one.", { n: "", note: "" }) + CARD("The representative", `${G2(F(1, "Name", "Marcus Andre Marsh"), F(2, "Title", "Administrator"))}`)),
  right: ROOM([`Attend with the death certificate. A witness who knew the family may be asked to confirm the heirs.`, `After the order, the representative takes an oath and the Clerk issues the <b>letters of office</b>.`, `Order several certified copies of the letters.`, `Enter the representative's name and title, and the dates in the Timeline card.`]),
  say: `The hearing. The judge reviews the petition and the list of heirs. A witness who knew the family may be asked to confirm the heirs under oath. Bring the death certificate. Then the court appoints the administrator. The representative takes an oath and the Clerk issues the letters of office. Order several certified copies, because the deed, the bank and the title company will each ask for one. Number one, enter the representative's name and title. Number two, enter the date of the order and the date of the letters in the timeline card, so the deadlines can start.` });

add({ part: "The steps", h: `Step: after appointment, <span class="lead">run the estate.</span>`, body: `<div class="grid3">
  <div class="box top"><h3>Open the estate</h3><p class="small">Get an employer identification number from the I R S. Open an estate bank account in the estate's name. Keep the estate's money apart from anyone's own.</p></div>
  <div class="box top"><h3>Protect the property</h3><p class="small">Tell the insurer. Collect rent into the estate account. Account for tenants' deposits. Pay property tax installments as they come due.</p></div>
  <div class="box top"><h3>Do not pay early</h3><p class="small">Do not pay creditors or distribute to heirs yet. The claims period and the order of payment matter. Keep every receipt.</p></div></div>`,
  say: `Once the letters issue, the representative runs the estate. Get an employer identification number from the I R S, and open an estate bank account in the estate's name. Keep the estate's money apart from anyone's own. Tell the insurer, because a vacant or rented building needs the right policy. Collect rent into the estate account, and account for tenants' security deposits. Pay property tax installments as they come due. File the final income tax returns. And do not pay creditors or distribute to heirs early. The claims period and the order of payment matter. Keep every receipt.` });

add({ part: "The steps", h: `Step: her credit report, <span class="gold">from all three bureaus.</span>`, left: FRAME(STEP("Request her credit report from all three bureaus (after the letters issue)", "Only people with legal authority can get a deceased person's credit report. Send each of the three bureaus its own request by certified mail, with the certified death certificate, the letters of office, and your photo ID. Then add every creditor you find to the Creditors box.", { n: "", links: ["Equifax", "Experian", "TransUnion"] })),
  right: ROOM([`Wait until the letters issue. Before then, build the creditor list from her mail and bills.`, `Send <b>each</b> bureau its own request by certified mail. One request does not reach the other two.`, `Include the death certificate, the letters of office, and your photo ID.`, `Add each creditor you find to the Creditors box. Keep the receipts in Documents.`]),
  say: `Her credit report is one way to find creditors you did not know about. Only people with legal authority can get it, such as the court appointed administrator, so do this once the letters issue. Before that, build your creditor list from her mail and bills. Send each of the three bureaus its own request by certified mail. Sending the death notice to one bureau does not reach the other two. Include a copy of the death certificate, the letters of office and your photo identification. Then add every creditor you find to the creditors card, and keep the certified mail receipts in the documents card.` });

add({ part: "The steps", h: `Steps: notice to creditors, <span class="lead">the inventory, and who receives.</span>`, left: FRAME(STEP("Publish and mail the notice to creditors, and let the claims period run", "Publish once a week for three successive weeks in a Cook County newspaper, and mail or deliver it to every creditor you know of. The claims deadline must be at least six months after the first publication, or three months after mailing to a known creditor, whichever is later.", { n: "" }) + STEP("Prepare and deliver the inventory of the estate", "Everything the estate owned as of the date of death. In a supervised estate it is filed with the Clerk within sixty days after the letters. In an independent estate it is mailed or delivered to each interested person.", { n: "" })),
  right: ROOM([`Publish three weeks in a row, <b>and</b> mail the notice to every known creditor. Publishing does not replace the search.`, `Enter the first publication date in the Timeline card.`, `The inventory lists what the estate owned on the date of death.`, `Confirm with counsel whether it is filed or delivered.`]),
  say: `Two more steps. First, the notice to creditors. Publish it once a week for three weeks in a Cook County newspaper, and mail it to every creditor you know of. Publishing does not replace the search. The claims deadline must be at least six months after the first publication, or three months after mailing to a known creditor, whichever is later. Number one, enter the first publication date in the timeline card and the page works out the dates. Second, the inventory of everything the estate owned on the date of death. Number two, confirm with counsel whether it is filed with the Clerk or delivered to each interested person.` });

add({ part: "The steps", h: `Steps: the deed, <span class="gold">signing, and recording.</span>`, left: FRAME(STEP("Draft the deed from the representative to the heir", "An independent representative who distributes real estate must record and deliver an instrument that contains the legal description and releases the estate's interest. Have the finished instrument checked by counsel or the title company before it is signed.", { n: "" }) + STEP("Sign before a notary and complete the transfer tax exemption and stamps", "Illinois requires an exemption statement on the deed or a transfer declaration. The City of Chicago stamp may also be needed. Ask the Recordings office or the title company which exemption applies.", { n: "" }) + STEP("Record the deed at the Cook County Clerk's Recordings office and keep the recorded copy", "Write the recorded document number and date in the note, and keep the recorded copy.", { n: "" })),
  right: ROOM([`The deed is drafted in this system, but it shows a <b>draft</b> mark until counsel approves it.`, `The representative signs in front of a notary, with the exemption statement.`, `Ask the Recordings office or the title company what they want to see.`, `Record it, write the document number in the note, and keep the recorded copy.`]),
  say: `Now the deed itself. An independent representative who distributes real estate must record and deliver an instrument that contains the legal description and releases the estate's interest. The deed in this system shows a draft mark across the page until counsel approves it. Have counsel or the title company check it before it is signed. The representative signs in front of a notary, with the transfer tax exemption statement, and the City of Chicago stamp may also be needed. Then record the deed at the Clerk's recordings office, write the recorded document number in the note, and keep the recorded copy.` });

add({ part: "The steps", h: `The closing steps, <span class="lead">and a finished case.</span>`, left: FRAME(STEP("Property transfer finished: a search by P I N shows the heir as the owner", "Search the Clerk's Recordings by each P I N again once the index catches up. When the heir is shown as owner, the property transfer is complete. That does not close the probate estate.", { n: "", status: "Done", note: "Searched 08/30/2026. Marcus A. Marsh shown as owner." }) + STEP("Close the probate estate (separate from the deed)", "The estate stays open until the claims period has ended and debts, taxes and expenses are paid. Do not pay creditors or distribute early.", { n: "" })),
  right: ROOM([`Also: deal with any recorded liens, and tell the Treasurer where the tax bill goes. The heir may qualify for a homeowner exemption.`, `Search again by each parcel number once the index catches up.`, `When the heir appears as owner, the transfer is complete.`, `But the estate is a separate matter. It closes only when the claims period ends and the debts are paid.`]),
  say: `The closing steps. Deal with any recorded liens and claims against the property. Tell the Treasurer where the tax bill goes, and check for exemptions. Then search the Clerk's recordings by each parcel number again, once the index catches up. When the heir appears as the owner, the property transfer is complete. But that does not close the estate. The probate estate closes only when the claims period has ended and debts, taxes and expenses are paid. Do not pay creditors or distribute early. Note the date the estate is closed. And that is the end of the steps.` });

// ---- PART 7: handoff cards ------------------------------------------------------------------------------------------
add({ part: "Handoff", h: `Court costs and the <span class="gold">preparation calendar.</span>`, left: FRAME(CARD("Court costs", `<ul class="ul"><li><b>Filing a new estate: $479</b> (with or without a will)</li><li><b>Certified death certificates:</b> $17 first copy, $6 each additional</li><li><b>Filing the will itself:</b> no fee</li><li><b>Newspaper publication</b> and <b>surety bond:</b> price varies; get a quote</li><li><b>Recording the deed:</b> ask the Recordings office</li></ul>`, "Fees change; confirm with the Clerk before filing.") + CARD("Preparation calendar", `<div class="hr hl">${B(1)}06/10/2026 · Consultation: Chicago Volunteer Legal Services</div>`)),
  right: ROOM([`The court costs card is a reference. Add your own quotes in the step notes.`, `The preparation calendar lists every step you gave a target date. Weekends and some holidays are flagged, because offices may be closed.`]),
  say: `Two reference cards. The court costs card lists the filing fee, which is four hundred seventy-nine dollars, the price of certified death certificates, that filing the will itself has no fee, and that publication, the bond and recording vary, so get a quote. Fees change, so confirm with the Clerk before filing. Number one, the preparation calendar lists every step you gave a target date. Weekends and some holidays are flagged, because offices may be closed. Check the specific office before you go.` });

add({ part: "Handoff", h: `Case handoff: <span class="lead">turnkey for counsel.</span>`, left: FRAME(CARD("Case handoff: turnkey for counsel", `${F(1, "Target date for the consultation", "06/10/2026")}<div class="hr hl">${B(2)}<span class="done">✓</span> Heirs list complete and double-checked · <span class="done">✓</span> Death certificate on file · <span class="open">○</span> Affidavit of heirship signed</div><div class="rw">${BTN(3, "Print the counsel packet (cover sheet and full case summary)", "pri")}</div>`, FIC)),
  right: ROOM([`When do you want the packet ready? Aim the date at your first appointment.`, `A readiness list shows what is done and what is still open. An item turns green only when the evidence is in.`, `Print the packet. It is a cover sheet and a full case summary a lawyer can read in minutes.`]),
  say: `Case handoff, which is where everything comes together. Number one, the target date for the consultation. Aim it at your first appointment. Number two, the readiness list. It shows what is done and what is still open, and an item turns green only when the evidence is in. Number three, press print the counsel packet. It is a cover sheet and a full case summary that a lawyer can read in minutes. The cover sheet asks for one thing: file it, and tell us any corrections, or tell us today that you cannot, so that we move on to our next scheduled consultation.` });

add({ part: "Handoff", h: `Who can open the case, <span class="gold">and the history.</span>`, left: FRAME(CARD("Case handoff: turnkey for counsel", `<h5>Who can open this case</h5><div class="hr">info@example.org · added by staff</div><div class="rw">${B(1)}<span class="in hl">Staff email to add</span>${BTN(2, "Add")}</div><h5>History</h5><div class="rw">${BTN(3, "Show who changed what", "")}</div><p class="mt hl2">${B(4)}04/05/2026 4:12 PM · Staff · Changed Date of death</p>`, FIC)),
  right: ROOM([`Type the email of a staff member who should be able to open this case.`, `Add them. Only the people listed can open the case.`, `The history button shows who changed what, and when.`, `Every change is logged. If two people edit at once, the page warns instead of overwriting.`]),
  say: `Two last pieces on the handoff card. Who can open this case. Number one, type the email of a staff member who should be able to open it. Number two, add them. Only the people listed can open the case. Then the history. Number three, the button shows who changed what, and when. Number four, every change is logged, with the person and the time. If two people edit at once, the page warns instead of overwriting. Reminder emails go to the people with access, so keep that list short and current.` });

add({ part: "Wrap-up", kind: "end", h: `You have walked the whole <span class="lead">page.</span>`, sub: "Gather the facts, keep the notes honest, and hand counsel a finished case.", body: `<div class="grid3"><div class="box top"><h3>Leave blanks blank</h3><p class="small">Never guess. The page keeps track of what is missing.</p></div><div class="box top"><h3>Certified mail only</h3><p class="small">Every notice, every person, with a number and a receipt.</p></div><div class="box top"><h3>Questions?</h3><p class="small">Write to <b>info@2ndchinc.org</b>. We answer by email.</p></div></div>`,
  say: `That is the whole page. You have seen every card and every kind of step, in the order you will use them. Three habits to keep. Leave blanks blank, and never guess. Send every notice by certified mail, with a number and a receipt for each person. And keep the notes honest, so the page can keep the case honest. When you are ready, open your own case and begin with the property card. If you have questions, write to us at I N F O at two N D C H I N C dot O R G, and we will answer by email. Thank you.` });

// ---- render --------------------------------------------------------------------------------------------------------
const slideHtml = (s, i) => {
  if (s.left && s.right && !s.left.includes('class="bd"')) s = { ...s, right: s.right.replace("In the room", "What to do") };
  const eyebrow = `<div class="eyebrow">${esc(s.part)} · ${i + 1} of ${slides.length}</div>`;
  let inner;
  if (s.kind === "cover") inner = `<div class="brand"><img src="/logo.png" alt="2nd Chance Housing logo"><div><b>2nd Chance Housing Inc</b><span>Instructor walkthrough</span></div></div>${eyebrow}<h1>${s.h}</h1><p class="lede">${esc(s.sub)}</p><p class="small">Press <b>Play</b> for the narrated version, or use the arrows. Space plays and pauses; C shows captions; F goes full screen.</p>`;
  else if (s.left) inner = `${eyebrow}<h2>${s.h}</h2><div class="wt"><div class="rep">${s.left}</div>${s.right}</div>`;
  else inner = `${eyebrow}<h2>${s.h}</h2>${s.sub ? `<p class="lede">${esc(s.sub)}</p>` : ""}${s.body || ""}`;
  return `<!-- ${i + 1} -->\n<section class="slide" data-say="${esc(s.say)}"><div class="card">\n${inner}\n</div></section>`;
};

let h = fs.readFileSync(root + "site/probate-help/index.html", "utf8");
const css = `
  /* walkthrough replica of the staff page */
  .wt{display:grid; grid-template-columns:minmax(0,1.35fr) minmax(0,.85fr); gap:16px; align-items:start;}
  @media (max-width:900px){ .wt{grid-template-columns:1fr;} }
  .fr{background:#fff; color:#17231C; border-radius:12px; overflow:hidden; border:1px solid var(--line); box-shadow:0 10px 30px rgba(0,0,0,.35);}
  .bar2{display:flex; align-items:center; gap:6px; padding:8px 12px; background:#E6EBE3;}
  .bar2 span{width:10px; height:10px; border-radius:50%; background:#B7C2B8;}
  .bar2 em{margin-left:10px; font:600 .72rem var(--sans); color:#506055; font-style:normal;}
  .pg{padding:12px; background:#F6F7F2; display:grid; gap:10px;}
  .pc{background:#fff; border:1px solid #D4DCD2; border-radius:10px; padding:11px 13px 11px 22px; position:relative; color:#17231C;}
  .pc h4{font:700 1rem var(--sans); margin:0 0 4px; color:#17231C;}
  .pc h5{font:700 .86rem var(--sans); margin:10px 0 4px;}
  .pc .mt,.mt{font:400 .8rem/1.45 var(--sans); color:#506055; margin:0 0 8px;}
  .g2{display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:8px;} @media (max-width:560px){ .g2{grid-template-columns:1fr;} }
  .fl{display:block; position:relative; margin-bottom:8px; font-size:.78rem; color:#506055;}
  .fl.hl{padding-left:2px;}
  .fl .lb{display:block; margin-bottom:3px; font-weight:600;}
  .in{display:block; border:1px solid #AEB9AE; border-radius:6px; padding:6px 9px; background:#fff; color:#17231C; font:500 .86rem/1.35 var(--sans); min-height:32px;}
  .in.ar{min-height:62px;} .in.empty{color:#93A598; font-style:italic;} .in.sl{display:flex; justify-content:space-between; gap:8px;} .in.sl b{color:#506055;}
  .in.wide{margin-top:8px; position:relative;}
  .bd{position:absolute; left:-17px; top:-3px; z-index:2; min-width:22px; height:22px; border-radius:11px; padding:0 6px; background:var(--gold); color:#17231C; font:800 .78rem/22px var(--sans); text-align:center; font-style:normal; box-shadow:0 1px 4px rgba(0,0,0,.35);}
  .in .bd{left:-14px; top:-9px;} .bt .bd{left:-14px; top:-9px;} .dec .bd{left:-14px; top:-4px;} .hr .bd{left:-14px; top:3px;}
  .hl .in,.bt.hl,.hr.hl,.hl2,.dec{outline:2px solid rgba(242,178,26,.55); outline-offset:1px;}
  .hl2{display:block; padding:4px 8px; border-radius:6px; position:relative;}
  .bt{display:inline-block; position:relative; border:1px solid #17231C; border-radius:6px; padding:6px 12px; margin:0 8px 6px 0; font:700 .8rem var(--sans); background:#fff; color:#17231C;}
  .bt.pri{background:#2E7D1F; border-color:#2E7D1F; color:#fff;}
  .rw{display:flex; flex-wrap:wrap; gap:6px; align-items:center; margin:6px 0; position:relative;} .rw .in{flex:1; min-width:140px;}
  .hr{position:relative; border:1px solid #D4DCD2; border-radius:8px; padding:7px 10px; margin:6px 0; font-size:.82rem; background:#FBFCFA;}
  .tg{background:#EEF2EA; border-radius:999px; padding:1px 8px; font-size:.72rem; font-weight:700; color:#506055;}
  .done{color:#2E7D1F; font-weight:800;} .open{color:#B47A0A; font-weight:800;}
  .ck{display:flex; align-items:flex-start; gap:8px;} .ck .lb{margin:0; font-weight:500;}
  .ck .bd{left:-17px;}
  .ck .cbx{flex:0 0 auto;} .ck .cbx{width:18px; height:18px; border:2px solid #506055; border-radius:4px; font:800 .8rem/14px var(--sans); text-align:center; color:#fff; background:#fff;} .ck .cbx.on{background:#2E7D1F; border-color:#2E7D1F;}
  .st h4{display:flex; gap:6px;} .sn{color:#B47A0A;}
  .dec{position:relative; margin:8px 0; padding:8px 10px; border-radius:8px; background:#FFF8E6; font-size:.82rem; display:grid; gap:4px;}
  .ch{display:block; position:relative; border:1px solid #AEB9AE; border-radius:6px; padding:4px 9px; font-size:.8rem; background:#fff;} .ch.on{border-color:#2E7D1F; background:#EAF4E4; font-weight:700;}
  .lk{display:flex; flex-wrap:wrap; gap:6px; margin:6px 0;} .lk span{font-size:.72rem; color:#2E7D1F; text-decoration:underline;}
  .ctl2{display:flex; gap:8px; margin-top:8px; flex-wrap:wrap;} .ctl2 .in{min-width:130px; position:relative;}
  .bar3{height:8px; border-radius:4px; background:#E6EBE3; overflow:hidden;} .bar3 i{display:block; height:100%; background:linear-gradient(90deg,#2E7D1F,#6BAF2E);}
  .sync{display:inline-block; position:relative; padding:4px 12px; border-radius:6px; background:#EAF4E4; color:#2E7D1F; font:700 .8rem var(--sans); width:max-content;}
  .ul{margin:0 0 0 18px; font-size:.82rem; color:#17231C;}
  .room{background:var(--surface); border:1px solid var(--line); border-radius:14px; padding:14px 16px;}
  .room h4{font:700 .72rem var(--sans); letter-spacing:.16em; text-transform:uppercase; color:var(--gold); margin-bottom:8px;}
  .room ol{list-style:none; counter-reset:r; display:grid; gap:9px;}
  .room li{counter-increment:r; position:relative; padding-left:34px; font-size:.9rem; line-height:1.45; color:var(--ink);}
  .room li::before{content:counter(r); position:absolute; left:0; top:0; min-width:24px; height:24px; border-radius:12px; background:var(--gold); color:#17231C; font:800 .8rem/24px var(--sans); text-align:center;}
  .room b{color:var(--gold);}
`;
h = h.replace("</style>", css + "</style>");
const first = h.indexOf("<main");
const last = h.indexOf("</main>");
h = h.slice(0, first) + `<main id="deck" aria-live="polite">\n\n` + slides.map(slideHtml).join("\n\n") + "\n\n" + h.slice(last);
// the captions box sat inside the original <main>; keep it or the engine throws on every slide change
h = h.replace("</main>", `<div id="cc" role="status" aria-live="off"></div>\n</main>`);
const rep = (a, b) => { if (!h.includes(a)) throw new Error("missing " + a.slice(0, 60)); h = h.split(a).join(b); };
rep(`/probate-help/audio/`,`/probate-help/walkthrough/audio/`);
rep(`/probate-help/img/`, `/probate-help/walkthrough/img/`);
rep(`<meta name="robots" content="index, follow">`, `<meta name="robots" content="noindex, follow">`);
h = h.replace(/<link rel="canonical"[^>]*>/, `<link rel="canonical" href="https://2ndchinc.org/probate-help/walkthrough/">`);
h = h.replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>\n?/, "");
h = h.replace(/<meta property="og:[^>]*>\n?/g, "");
h = h.replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="An instructor-led walkthrough of the property transfer case page, field by field, with a fictional practice family. A preparation tool, not legal advice.">`);
h = h.replace(/<title>[^<]*<\/title>/, `<title>Walkthrough: Filling In the Transfer Case Page · 2nd Chance Housing</title>`);
h = h.replace(`<div class="banner">A preparation tool from 2nd Chance Housing Inc. We are not a law firm and nothing here is legal advice. Your lawyer and the court decide the route, the filings and the fees.</div>`,
  `<div class="banner">Instructor walkthrough with a fictional practice family. A preparation tool from 2nd Chance Housing Inc. Not a law firm; nothing here is legal advice.</div>`);
h = h.replace(/<span class="count" id="count">[^<]*<\/span>/, `<span class="count" id="count">1 / ${slides.length}</span>`);
fs.mkdirSync(root + "site/probate-help/walkthrough/audio", { recursive: true });
fs.writeFileSync(root + "site/probate-help/walkthrough/index.html", h);
fs.writeFileSync(root + "docs/walkthrough-narration.txt", slides.map((s) => s.say.trim()).join("\n\n\n\n") + "\n");
const words = slides.reduce((a, s) => a + s.say.split(/\s+/).length, 0);
const digits = slides.filter((s) => /\d/.test(s.say)).map((s, i) => i);
console.log("slides:", slides.length, "words:", words, "~minutes:", (words / 150).toFixed(1), "say-with-digits:", digits.length);
